package codicefiscale

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"time"
)

// names.txt.gz is generated by tools/go-migration/codicefiscale_data.py: the
// 'name' of every option of the codes index, in lookup order.
//
//go:embed names.txt.gz
var namesGz []byte

var (
	namesOnce   sync.Once
	namesLoaded map[string][]string
	namesErr    error
)

func loadNames() (map[string][]string, error) {
	namesOnce.Do(func() {
		zr, err := gzip.NewReader(bytes.NewReader(namesGz))
		if err != nil {
			namesErr = fmt.Errorf("codicefiscale: open names: %w", err)
			return
		}
		defer zr.Close()
		names := map[string][]string{}
		sc := bufio.NewScanner(zr)
		for sc.Scan() {
			fields := strings.Split(sc.Text(), "\t")
			if len(fields) < 2 {
				namesErr = fmt.Errorf("codicefiscale: names entry %q", sc.Text())
				return
			}
			names[fields[0]] = fields[1:]
		}
		namesLoaded, namesErr = names, sc.Err()
	})
	return namesLoaded, namesErr
}

// errWrongCIN carries the control character decode() expected.
type errWrongCIN struct{ expected string }

func (errWrongCIN) Error() string { return "codicefiscale: wrong CIN" }

// decodedName ports decode(code)['birthplace']['name'].
func decodedName(data *lookupData, names map[string][]string, code string, now time.Time) (string, error) {
	slug, err := slugify(code)
	if err != nil {
		return "", err
	}
	code = strings.ToUpper(strings.ReplaceAll(slug, "-", ""))
	if !validSyntax(code) {
		return "", ErrInvalid
	}
	yearValue, err := strconv.Atoi(decodeOmocodia(code[6:8]))
	if err != nil {
		return "", ErrInvalid
	}
	month := strings.IndexByte(months, code[8]) + 1
	day, err := strconv.Atoi(decodeOmocodia(code[9:11]))
	if err != nil {
		return "", ErrInvalid
	}
	if day > 40 {
		day -= 40
	}
	currentYear := now.Year()
	prefix := strconv.Itoa(currentYear)
	prefix = prefix[:max(len(prefix)-2, 0)]
	suffix := strconv.Itoa(yearValue)
	if len(suffix) < 2 {
		suffix = "0" + suffix
	}
	birthYear, err := strconv.Atoi(prefix + suffix)
	if err != nil {
		return "", ErrInvalid
	}
	if birthYear > currentYear {
		birthYear -= 100
	}
	date, err := getDate(strconv.Itoa(birthYear)+"/"+strconv.Itoa(month)+"/"+strconv.Itoa(day), now)
	if err != nil {
		return "", ErrInvalid
	}
	// The codes index: no code slug is a municipality or country key.
	placeCode := code[11:12] + decodeOmocodia(code[12:15])
	options := data.codes[placeCode]
	if len(options) != len(names[placeCode]) {
		return "", ErrInvalid
	}
	chosen := -1
	for i, p := range options {
		if (p.created.IsZero() || !date.Before(p.created)) && (p.deleted.IsZero() || !date.After(p.deleted)) {
			chosen = i
			break
		}
	}
	if chosen < 0 {
		for i := 0; i+1 < len(options); i++ {
			p, next := options[i], options[i+1]
			if p.deleted.IsZero() || next.created.IsZero() {
				continue
			}
			if !date.Before(p.deleted) && !p.deleted.After(next.created) {
				chosen = i + 1
				if !p.created.IsZero() && p.deleted.Sub(p.created) <= 24*time.Hour {
					chosen = i
				}
				break
			}
		}
	}
	if chosen < 0 {
		return "", ErrInvalid
	}
	cin, err := encodeCIN(code)
	if err != nil {
		return "", ErrInvalid
	}
	if cin != code[15:] {
		return "", errWrongCIN{expected: cin}
	}
	return names[placeCode][chosen], nil
}

// DecodedBirthplaceName is the birthplace name of the application's
// get_data_from_italian_fiscal_code(code): codicefiscale.decode(code), once
// more with the expected control character in place of the last character
// when only that one is wrong. found is false where the helper returns None
// (every exception). ErrUnsupported marks a code outside the ported
// transliteration subset.
func DecodedBirthplaceName(code string, now time.Time) (name string, found bool, err error) {
	data, err := loadData()
	if err != nil {
		return "", false, err
	}
	names, err := loadNames()
	if err != nil {
		return "", false, err
	}
	name, err = decodedName(data, names, code, now)
	var wrong errWrongCIN
	if errors.As(err, &wrong) {
		runes := []rune(code)
		name, err = decodedName(data, names, string(runes[:len(runes)-1])+wrong.expected, now)
	}
	if errors.Is(err, ErrUnsupported) {
		return "", false, err
	}
	if err != nil {
		return "", false, nil
	}
	return name, true, nil
}
